import math

def shipping_cost(weight_kg, express):
    # under 1 kg -> 4; 1 to 5 kg (inclusive) -> 9; over 5 kg -> 9 + 2 per started extra kg
    # express doubles the total
    if weight_kg < 1:
        cost = 4
    if weight_kg <= 5:
        cost = 9
    else:
        extra = math.ceil(weight_kg - 5)
        cost = 9 + 2 * extra
    if express:
        cost = cost * 2
